from . import register


def quests():
    out,add=register('C')
    W=['','a','abba','aabccc','red moon','  A b  ','кот кот','ab#c##d','01230','a-b-a']
    A=[[],[0],[1,2,3],[3,-1,0,3],[2,2,2,1],[-3,4,-2,5],[5,0,0,2,1],[1,-1,1,-1],[7,3,9,2,0]]
    N=[0,1,2,3,7,10,25,99,123,1001]
    add('backspace_scroll','Свиток с кнопкой назад','data — строка. Символ # удаляет последний уже записанный символ; на пустом тексте ничего не делает. Остальные символы дописываются. Верни конечный текст.','out=[]\nfor c in data:\n    if c=="#":\n        if out: out.pop()\n    else: out.append(c)\nreturn "".join(out)',W,'strings')
    add('caps_latch','Клавиша с защёлкой','data — строка. Символ ^ переключает режим CAPS, изначально выключенный, и сам не выводится. При включённом CAPS буквы переводятся в верхний регистр, остальные символы сохраняются. Верни вывод.','caps=False; out=[]\nfor c in data:\n    if c=="^": caps=not caps\n    else: out.append(c.upper() if caps else c)\nreturn "".join(out)',['','abc','^abc','a^bc^d','^^a','^кот^ мир','1^a2','a^^b^c'],'strings')
    add('escaped_separator','Труба с экранированием','data — строка. Разбей по неэкранированным |. Обратная косая черта экранирует ровно следующий символ и исчезает; одиночная последняя черта сохраняется. Пустые части учитывай.','out=[""]; escaped=False\nfor c in data:\n    if escaped: out[-1]+=c; escaped=False\n    elif c==chr(92): escaped=True\n    elif c=="|": out.append("")\n    else: out[-1]+=c\nif escaped: out[-1]+=chr(92)\nreturn out',['','|','a|b','a\\|b|c','a\\','a\\\\|b','||','\\x|y'],'strings')
    add('whisper_codec','Шёпот лесного передатчика','data — строка. После каждой латинской строчной гласной aeiou передатчик добавляет p и ту же гласную. Остальные символы сохраняй. Верни закодированный текст.','return "".join(c+"p"+c if c in "aeiou" else c for c in data)',W,'strings')
    add('alien_vowels','Колесо инопланетных гласных','data — строка. Замени a→e→i→o→u→a, то же для прописных букв. Остальные символы не меняй.','return data.translate(str.maketrans("aeiouAEIOU","eiouaEIOUA"))',W+['AEIOU','unique'],'strings')
    add('zipper_word','Молния из краёв слова','data — строка. Читай по очереди первый, последний, второй, предпоследний символ и так далее, каждый символ один раз. Верни строку.','out=[]; l=0; r=len(data)-1\nwhile l<=r:\n    out.append(data[l]); l+=1\n    if l<=r: out.append(data[r]); r-=1\nreturn "".join(out)',W,'strings')
    add('morse_time','Время точек и тире','data — строка из . и -. Точка длится 1, тире 3; между соседними символами пауза 1. Для пустой строки время 0. Верни длительность.','return sum(1 if c=="." else 3 for c in data)+max(0,len(data)-1)',['','.','-','...','---','.-.-','..--..','-..-.'],'strings')
    add('glyph_holes','Дырочки в номере','data — строка из цифр. Цифры 0,6,9 содержат по одной дырочке, 8 — две, остальные ноль. Верни число дырочек.','return sum(2 if c=="8" else 1 if c in "069" else 0 for c in data)',['','0','8','123','6098','888','0001','9876543210'],'strings')
    add('roman_tokens','Римские жетоны','data — корректная римская запись числа 1..3999 либо пустая строка. Переведи в целое; пустая даёт 0. Допустимы IV,IX,XL,XC,CD,CM.','values={"I":1,"V":5,"X":10,"L":50,"C":100,"D":500,"M":1000}\nreturn sum(-values[c] if i+1<len(data) and values[c]<values[data[i+1]] else values[c] for i,c in enumerate(data))',['','I','IV','IX','XLII','XCIX','CDXLIV','MCMXCIV','MMMCMXCIX'],'strings')
    add('number_runs','Числа в телеграмме','data — строка. Верни список целых чисел, образованных максимальными непрерывными сериями ASCII-цифр. Минусы не относятся к числу, ведущие нули игнорируются.','return [int(x) for x in re.findall(r"[0-9]+",data)]',['','a12b003','-7 and +9','42','a0b0','١٢3','123abc456','x1.2e3'],'strings')
    add('hex_lamps','Цвет трёх ламп','data — строка ровно из трёх шестнадцатеричных цифр RGB, регистр произвольный. Разверни каждую цифру в две и верни строку #rrggbb в нижнем регистре.','return "#"+"".join(c.lower()*2 for c in data)',['000','fff','F0a','123','abc','909','00F','eD7'],'strings')
    add('telephone_pause','Телефон с паузами','data — строка из цифр и запятых. Каждая цифра занимает 1 единицу времени, запятая — 2. Верни моменты окончания передачи каждой цифры, паузы сами не выводятся.','time=0; out=[]\nfor c in data:\n    time+=2 if c=="," else 1\n    if c!=",": out.append(time)\nreturn out',['','1',',1','12,3',',,','1,,2','0,0,0','12345'],'strings')
    add('word_train','Поезд из слов','data — предложение, слова разделены любым whitespace. Верни bool: последняя буква каждого слова без учёта регистра равна первой букве следующего. Для 0 или 1 слова True.','words=data.lower().split()\nreturn all(a[-1]==b[0] for a,b in zip(words,words[1:]))',['','moon','red dog','cat tree egg','A a A','кот ток','a b',' north\nhero owl '],'strings')
    add('vowelless_identity','Безгласный паспорт','data — строка. Удали латинские гласные без учёта регистра, но сохрани гласную, если она первый символ строки. Остальные символы не меняй.','return "".join(c for i,c in enumerate(data) if i==0 or c.lower() not in "aeiou")',W+['AEIOU','orange'],'strings')
    add('word_mirror_index','Зеркало каждого второго','data — строка с произвольными пробельными разделителями. Переверни слова с нечётными индексами (1,3…), чётные сохрани. Соедини одним пробелом.','return " ".join(w[::-1] if i%2 else w for i,w in enumerate(data.split()))',W,'strings')
    add('initial_word_lengths','Забор из длин','data — предложение. Для каждого слова выведи первую букву столько раз, какова длина слова. Слова раздели одним пробелом; пробелы входа нормализуй.','return " ".join(w[0]*len(w) for w in data.split())',W,'strings')
    add('longest_token_tie','Слово у выхода','data — предложение. Верни последнее из самых длинных слов; для пустого набора слов верни пустую строку.','words=data.split()\nreturn max(reversed(words),key=len) if words else ""',W,'strings')
    add('punctuation_space','Пунктуация на конвейере','data — строка. Перед каждым из ,.!? удали все непосредственно предшествующие обычные пробелы; другие символы и пробелы сохрани.','return re.sub(r" +([,.!?])",r"\1",data)',['','a , b !','hello  !','a  b','   ?','x. y',' . !','a\t !'],'strings')
    add('mail_mask','Письмо невидимке','data — строка ровно с одним @ и непустой левой частью. Замени все символы слева от @, кроме первого, звёздочками; домен сохрани.','name,domain=data.split("@")\nreturn name[0]+"*"*(len(name)-1)+"@"+domain',['a@b','ab@host','alice@example.org','x@','кот@дом','123@x','long.name@site','A@B'],'strings')
    add('isbn_checksum','Последняя цифра ISBN','data — строка из девяти ASCII-цифр. Вычисли ISBN-10: сумма цифр с весами 10,9,…,2 плюс контрольный символ должна делиться на 11. Верни контрольный символ 0..9 или X для 10.','x=(-sum((10-i)*int(c) for i,c in enumerate(data)))%11\nreturn "X" if x==10 else str(x)',['000000000','030640615','123456789','111111111','999999999','013110362','020163361','007462542'],'strings')
    add('luhn_tail','Контрольная лампа карты','data — непустая строка из ASCII-цифр без контрольной цифры. Добавление справа одной цифры должно дать корректную сумму Луна: начиная со второй справа, удваивай через одну, значения >9 уменьши на 9. Верни контрольную цифру числом.','total=0\nfor i,c in enumerate(reversed(data)):\n    x=int(c)*(2 if i%2==0 else 1)\n    total+=x-9 if x>9 else x\nreturn (-total)%10',['0','1','9','7992739871','12345','00000','42','987654321'],'strings')
    add('tiny_run_decode','Свиток коротких серий','data — строка из пар: латинская буква и одна цифра 0..9 (например a3b0), либо пустая. Раскрой пары в повторения буквы.','return "".join(data[i]*int(data[i+1]) for i in range(0,len(data),2))',['','a0','a1','a3b2','Z2x0','a9','b1a2b1','x2Y3z1'],'strings')
    add('space_parity','Чередующиеся пробелы','data — строка. Удали первый, третий, пятый и так далее обычные пробелы по порядку появления; второй, четвёртый и остальные символы сохрани.','n=0; out=[]\nfor c in data:\n    if c==" ":\n        n+=1\n        if n%2: continue\n    out.append(c)\nreturn "".join(out)',W,'strings')
    add('bracket_depth_simple','Глубина круглой пещеры','data — строка из скобок ( и ). Верни максимальную глубину вложенности, если последовательность корректна, иначе -1. Пустая корректна с глубиной 0.','depth=best=0\nfor c in data:\n    depth+=1 if c=="(" else -1\n    if depth<0: return -1\n    best=max(best,depth)\nreturn best if depth==0 else -1',['','()','(())','()()','(()','())(',')(','((()))()'],'strings')
    add('alternating_markers','Чередование двух символов','data — строка. Верни bool: в ней не более двух разных символов, а любые соседи различаются. Пустая и одиночная подходят.','return len(set(data))<=2 and all(a!=b for a,b in zip(data,data[1:]))',['','a','ab','abab','aba','abba','abc','0101010'],'strings')
    add('bouncing_ball','Мяч у стен','data=[длина,шаги], длина≥1, шаги≥0. Мяч начинает в 0, идёт вправо по одной клетке и отражается от стен 0 и длина. Верни позицию через шаги ходов.','length,t=data\np=t%(2*length)\nreturn min(p,2*length-p)',[[1,0],[1,3],[5,5],[5,6],[5,10],[7,23],[2,100],[10,19]],'math_ops')
    add('battery_bounce','Зарядка с охлаждением','data=[цель,прирост], цель≥0, прирост≥1. За минуту батарея получает прирост, но после каждой третьей минуты теряет 1 (не ниже 0). Верни минуты до первого достижения цели; достижение проверяется после возможной потери.','target,gain=data\ncharge=t=0\nwhile charge<target:\n    t+=1; charge+=gain\n    if t%3==0: charge=max(0,charge-1)\nreturn t',[[0,1],[1,1],[3,1],[4,2],[10,3],[20,1],[17,4],[100,7]],'loops')
    add('queue_robot','Очередь роботов','data — список целых id. Отрицательный id в начале очереди уходит в конец со сменой знака; положительный или ноль уходит на обслуживание навсегда. Повторяй до пустой очереди. Верни порядок обслуживания.','q=deque(data); out=[]\nwhile q:\n    x=q.popleft()\n    if x<0: q.append(-x)\n    else: out.append(x)\nreturn out',A,'loops')
    add('elevator_log','Лифт с нижним упором','data — список целых смещений лифта. Старт на этаже 0, ниже 0 спускаться нельзя: каждое смещение ограничивается снизу 0. Верни конечный этаж.','floor=0\nfor step in data: floor=max(0,floor+step)\nreturn floor',A,'loops')
    add('minimum_start_fuel','Запас до первого маяка','data — изменения топлива по шагам, целые числа. Найди минимальное начальное топливо, чтобы после каждого шага и на старте оставалось не меньше 1.','total=low=0\nfor x in data:\n    total+=x; low=min(low,total)\nreturn 1-low',A,'loops')
    add('lantern_streak','Фонарь выдерживает два','data — список целых сигналов. Положительный сигнал включает фонарь. Неположительный выключает его только после двух таких сигналов подряд. Изначально выключен. Верни список bool после каждого сигнала.','on=False; misses=0; out=[]\nfor x in data:\n    if x>0: on=True; misses=0\n    else:\n        misses+=1\n        if misses>=2: on=False\n    out.append(on)\nreturn out',A,'loops')
    add('recharge_coupons','Купоны на следующее','data — неотрицательные цены покупок. За каждую покупку с фактической ценой ≥10 дают один купон, который уменьшает следующую покупку на 3 (не ниже 0). Все купоны обязательно применяются к ближайшей покупке. Верни сумму оплаты.','coupon=total=0\nfor price in data:\n    pay=max(0,price-coupon); total+=pay\n    coupon=3 if pay>=10 else 0\nreturn total',[[],[0],[10],[10,10],[12,2,12],[9,9],[20,20,20],[10,13,5,30]],'loops')
    add('happy_steps','Число, которое улыбается','data — положительное целое. Повторяй замену числа суммой квадратов цифр. Верни bool: дойдёт ли процесс до 1; при цикле False.','seen=set()\nwhile data!=1 and data not in seen:\n    seen.add(data); data=sum(int(c)**2 for c in str(data))\nreturn data==1',[1,2,7,19,20,28,99,100],'loops')
    add('digital_persistence','Цифровая настойчивость','data — неотрицательное целое. Пока число двузначное или больше, заменяй его произведением цифр. Верни число замен.','steps=0\nwhile data>=10:\n    p=1\n    for c in str(data): p*=int(c)\n    data=p; steps+=1\nreturn steps',N+[39,77,999],'loops')
    add('collatz_peak','Высшая точка тройки','data — положительное целое ≤1000. В процессе Коллатца чётное делится на 2, нечётное заменяется на 3n+1, до 1. Верни максимальное встреченное число, включая старт.','peak=data\nwhile data!=1:\n    data=data//2 if data%2==0 else 3*data+1\n    peak=max(peak,data)\nreturn peak',[1,2,3,6,7,11,27,97],'loops')
    add('reverse_add_once','Зеркальный шаг числа','data — неотрицательное целое. Прибавь к числу число из перевёрнутой десятичной записи и верни bool: является ли сумма палиндромом.','s=str(data+int(str(data)[::-1]))\nreturn s==s[::-1]',N+[56,89,196],'math_ops')
    add('octal_alarm','Цифра семь в восьмеричном','data — неотрицательное целое. Верни число цифр 7 в его восьмеричной записи.','return oct(data)[2:].count("7")',N+[63,511,4095],'math_ops')
    add('ternary_balance','Троичная чашка','data — неотрицательное целое. Переведи в обычную троичную систему. Верни число цифр 1 минус число цифр 2; для 0 верни 0.','score=0\nwhile data:\n    digit=data%3; score+=(digit==1)-(digit==2); data//=3\nreturn score',N,'math_ops')
    add('kaprekar_step','Шаг Капрекара','data — число 0..9999. Из цифр четырёхзначной записи с ведущими нулями составь наибольшее и наименьшее числа и верни разность.','s=sorted(f"{data:04d}")\nreturn int("".join(s[::-1]))-int("".join(s))',[0,1,1111,1234,6174,2005,9999,1000],'strings')
    add('digit_drop','Пропавшая максимальная цифра','data — неотрицательное целое. Удали первое слева вхождение наибольшей цифры. Верни оставшееся число; пустая запись даёт 0.','s=str(data); i=s.index(max(s))\nreturn int(s[:i]+s[i+1:] or "0")',N+[909,777,1203],'strings')
    add('binary_runs_one','Островки двоичных единиц','data — неотрицательное целое. Верни число непрерывных серий единиц в двоичной записи.','return len(re.findall("1+",bin(data)[2:]))',N+[15,85,255],'strings')
    add('digit_spiral_sum','Шахматная сумма цифр','data — строка из ASCII-цифр. Складывай цифры на чётных индексах и вычитай на нечётных, начиная слева. Верни целое число.','return sum(int(c)*(1 if i%2==0 else -1) for i,c in enumerate(data))',['','0','12','123','9090','0007','123456789','77777'],'strings')
    add('near_palindrome','Одна царапина на зеркале','data — строка. Верни bool: можно ли сделать её палиндромом заменой не более одного символа (удалять нельзя).','return sum(a!=b for a,b in zip(data[:len(data)//2],reversed(data[len(data)-len(data)//2:])))<=1',['','a','ab','abcd','abca','racecar','abccaa','abcdef'],'strings')
    add('unique_middle_word','Центральное слово','data — предложение. Если слов нечётное количество, верни центральное слово; иначе верни два центральных через /. Для отсутствия слов верни пустую строку.','w=data.split(); n=len(w)\nreturn "" if not n else w[n//2] if n%2 else w[n//2-1]+"/"+w[n//2]',W+['a b c d e'],'strings')
    add('word_end_chain','Хвосты вместо голов','data — предложение. Построй строку из последних символов всех слов в исходном порядке. Для отсутствия слов верни пустую.','return "".join(w[-1] for w in data.split())',W,'strings')
    add('mirror_case_pair','Антиподы регистра','data=[a,b] — строки. Верни bool: строки различаются, но совпадают после casefold().','a,b=data\nreturn a!=b and a.casefold()==b.casefold()',[['a','A'],['a','a'],['Straße','STRASSE'],['',''],['кот','КОТ'],['ab','ac'],['Hello','hELLO'],['1','1']],'strings')
    add('vowels_islands','Гласные острова','data — строка. Найди максимальную длину непрерывного участка из латинских гласных aeiou без учёта регистра. Если гласных нет, 0.','return max((len(m.group()) for m in re.finditer(r"[aeiou]+",data,re.I)),default=0)',W+['AEIxxou','queue'],'strings')
    add('alternating_cipher','Шифр через букву','data — строка. Сначала выпиши символы с индексами 0,2,4…, затем символы с индексами 1,3,5… в обратном порядке. Верни строку.','return data[::2]+data[1::2][::-1]',W,'strings')
    add('column_tabs','Табуляция по колонкам','data=[k,строка], k≥1. Символ табуляции заменяет столько пробелов, чтобы следующая позиция стала кратна k (даже в позиции 0 добавь k). Перевод строки сохраняется и сбрасывает колонку в 0. Остальные символы имеют ширину 1. Верни развёрнутый текст.','width,text=data; column=0; out=[]\nfor c in text:\n    if c==chr(9): n=width-column%width; out.append(" "*n); column+=n\n    elif c==chr(10): out.append(c); column=0\n    else: out.append(c); column+=1\nreturn "".join(out)',[[4,''],[4,'a\tb'],[4,'\t'],[2,'ab\tc'],[3,'a\tb\tc'],[4,'ab\n\tx'],[1,'x\ty'],[4,'кот\tдом']],'strings')
    add('word_rank_code','Номер буквы в алфавите','data — строка из латинских букв и пробелов. Замени каждую букву её номером 1..26, регистр игнорируется, пробел кодируется 0. Верни список чисел.','return [0 if c==" " else ord(c.lower())-96 for c in data]',['','a','AZ','Hello World','  ','moon','x y z','A a'],'strings')
    add('move_only_vowels','Гласные идут назад','data — строка. Разверни порядок только латинских гласных aeiouAEIOU, оставляя остальные символы на местах. Регистр перемещается вместе с буквой.','v=[c for c in data if c in "aeiouAEIOU"]\nreturn "".join(v.pop() if c in "aeiouAEIOU" else c for c in data)',W+['AEiou','hello world'],'strings')
    add('keyboard_one_left','Клавиши съехали влево','data — строка из символов qwertyuiop. Каждый символ замени его левым соседом на этой строке клавиатуры; q остаётся q.','row="qwertyuiop"\nreturn "".join(row[max(0,row.index(c)-1)] for c in data)',['','q','w','qwerty','pop','type','wire','uiop'],'strings')
    add('nested_quotes_extract','Последний остров в кавычках','data — строка. Кавычка " переключает нахождение внутри цитаты, экранирования нет. Верни последний завершённый фрагмент между парами кавычек; незакрытый игнорируй. Если завершённых нет, пустая строка.','parts=data.split(chr(34))\nreturn parts[-2] if len(parts)%2==1 and len(parts)>1 else parts[-3] if len(parts)>2 else ""',['','"a"','x "a" y "b"','"a','"a" "b','""','x','"ab"cd"ef"'],'strings')
    add('rle_escape_digits','Сжатие без путаницы','data — строка. Верни список словарей {"char": символ, "count": длина} для максимальных серий символов. Цифры считаются обычными символами.','return [{"char":c,"count":len(list(g))} for c,g in itertools.groupby(data)]',W,'strings')
    add('rotating_wheel_words','Слова на колесе','data=[строка,k], k — любое целое. Разбей строку на слова и циклически сдвинь слова вправо на k. Верни список слов. Для пустого набора [].','s,k=data; w=s.split()\nif not w: return []\nk%=len(w)\nreturn w[-k:]+w[:-k] if k else w',[['',0],['a',3],['a b c',1],['a b c',-1],['x y',0],['one two three',7],[' a  b ',2],['кот дом лес',-4]],'lists')
    add('train_coupling','Вагоны с повреждённой сцепкой','data — список целых чисел. Ноль разрывает состав, ненулевые образуют группы. Верни суммы групп; пустые группы не выводи.','out=[]; current=0; active=False\nfor x in data+[0]:\n    if x: current+=x; active=True\n    elif active: out.append(current); current=0; active=False\nreturn out',A,'lists')
    add('neighbor_sandwich','Число между близнецами','data — список целых. Верни элементы, у которых есть оба соседа и эти соседи равны друг другу, но отличаются от самого элемента. Сохрани порядок и повторы.','return [data[i] for i in range(1,len(data)-1) if data[i-1]==data[i+1]!=data[i]]',A+[[1,2,1],[3,1,3,1,3]],'lists')
    add('domino_counts','Домино из нулей','data — список целых. Посчитай, сколько непересекающихся пар соседних нулей можно выбрать максимум. Каждый элемент разрешено использовать один раз.','count=run=0\nfor x in data:\n    if x==0:\n        run+=1\n        if run==2: count+=1; run=0\n    else: run=0\nreturn count',A+[[0,0],[0,0,0,0,0]],'loops')
    add('parity_compress','Чётность как переключатель','data — список целых. В каждой максимальной серии одинаковой чётности сохрани только последний элемент. Верни список.','return [x for i,x in enumerate(data) if i==len(data)-1 or x%2!=data[i+1]%2]',A,'lists')
    add('local_repair','Ремонт одиночной ямы','data — список целых высот. Одновременно замени каждый внутренний элемент, строго меньший обоих соседей, минимумом двух исходных соседей. Края сохрани.','return [min(data[i-1],data[i+1]) if 0<i<len(data)-1 and x<min(data[i-1],data[i+1]) else x for i,x in enumerate(data)]',A,'lists')
    add('stepping_marks','Следы через расстояние','data — список целых смещений. Начни в позиции 0, после каждого смещения запиши позицию, но подряд одинаковые позиции не дублируй. Начальную позицию включи.','out=[0]; p=0\nfor x in data:\n    p+=x\n    if p!=out[-1]: out.append(p)\nreturn out',A,'loops')
    add('adjacent_cancel','Взаимное уничтожение зарядов','data — список целых. Слева направо добавляй числа в стек: если новое равно минусу вершины, удали вершину и новое; иначе добавь. Нули тоже уничтожают друг друга. Верни стек.','out=[]\nfor x in data:\n    if out and out[-1]==-x: out.pop()\n    else: out.append(x)\nreturn out',A,'lists')
    add('pair_larger_first','Парные дуэли','data — список чисел. Для каждой непересекающейся пары выведи сначала большее, затем меньшее; последний одиночный элемент сохрани.','out=[]\nfor i in range(0,len(data),2): out.extend(sorted(data[i:i+2],reverse=True))\nreturn out',A,'lists')
    add('third_stream','Каждый третий забывает','data — список чисел. Поток удаляет каждый третий элемент с нумерацией с 1, но счётчик после нуля сбрасывается и сам ноль сохраняется. Верни выжившие.','out=[]; count=0\nfor x in data:\n    if x==0: count=0; out.append(x)\n    else:\n        count+=1\n        if count%3: out.append(x)\nreturn out',A,'loops')
    add('cyclic_difference','Замкнутый контур датчиков','data — список чисел. Верни разности между следующим и текущим элементами по кольцу, включая переход последнего к первому. Пустой вход даёт [].','return [data[(i+1)%len(data)]-x for i,x in enumerate(data)]',A,'lists')
    add('leave_one_repeat','Одна копия из каждого конца','data — список чисел. Для каждого значения сохрани первое и последнее вхождения; если вхождение одно, сохрани один раз. Исходный порядок не меняй.','first={}; last={}\nfor i,x in enumerate(data):\n    first.setdefault(x,i); last[x]=i\nreturn [x for i,x in enumerate(data) if i==first[x] or i==last[x]]',A,'dicts')
    add('record_reset_zero','Рекорды после перезагрузки','data — список чисел. Ноль сбрасывает рекорд и сам не выводится. В каждом участке между нулями выведи строгие рекорды максимума, включая первый элемент участка.','out=[]; best=None\nfor x in data:\n    if x==0: best=None\n    elif best is None or x>best: best=x; out.append(x)\nreturn out',A,'loops')
    add('one_swap_sorted','Один обмен спасает строй','data — список целых. Верни bool: можно ли сделать его неубывающим, обменяв не более двух позиций один раз. Исходно отсортированный подходит.','target=sorted(data); bad=[i for i in range(len(data)) if data[i]!=target[i]]\nreturn len(bad) in (0,2)',A+[[1,3,2],[3,2,1],[2,3,1]],'lists')
    add('pendulum_sort','Маятниковая расстановка','data — список чисел. Отсортируй, затем выпиши минимум, максимум, второй минимум, второй максимум и так далее. Каждый элемент один раз.','a=sorted(data); out=[]; l=0; r=len(a)-1\nwhile l<=r:\n    out.append(a[l]); l+=1\n    if l<=r: out.append(a[r]); r-=1\nreturn out',A,'lists')
    add('relative_temperature','Сравнение с предыдущим живым','data — список целых температур, ноль означает пропуск. Для каждого ненулевого значения после первого ненулевого верни -1,0,1 по сравнению с предыдущим ненулевым. Пропуски не выводи.','last=None; out=[]\nfor x in data:\n    if x:\n        if last is not None: out.append((x>last)-(x<last))\n        last=x\nreturn out',A,'loops')
    add('delayed_echo','Эхо с задержкой на шаг','data — список целых сигналов. В момент i выход равен data[i] плюс половина предыдущего исходного сигнала, округлённая вниз. Для первого предыдущий 0. Верни список.','return [x+(data[i-1]//2 if i else 0) for i,x in enumerate(data)]',A,'lists')
    add('saturating_accumulator','Переполненный счётчик','data — список изменений. Счётчик начинается с 5 и после каждого изменения ограничивается интервалом 0..10. Верни число раз, когда произошло именно ограничение (до ограничения значение было вне интервала).','value=5; count=0\nfor x in data:\n    raw=value+x; count+=int(raw<0 or raw>10); value=min(10,max(0,raw))\nreturn count',A+[[20],[-20],[5,1,-12]],'loops')
    add('walk_return_times','Встречи с началом пути','data — список целых шагов. Старт в 0. Верни индексы шагов, после которых позиция снова равна 0. Начальный момент не выводи.','position=0; out=[]\nfor i,x in enumerate(data):\n    position+=x\n    if position==0: out.append(i)\nreturn out',A,'loops')
    add('stairs_energy','Усталость на лестнице','data — последовательность высот ступеней, старт на высоте 0. Подъём стоит разницу высот, спуск бесплатен. Верни суммарную затраченную энергию.','last=cost=0\nfor height in data:\n    cost+=max(0,height-last); last=height\nreturn cost',A,'loops')
    add('traffic_lights','Светофор с фазами','data — строка из W (ждать) и B (нажать кнопку). Изначально красный. W меняет red→green→yellow→red. B на красном сразу включает зелёный, в других состояниях ничего не делает. Верни список состояний после каждой команды.','state=0; out=[]; names=["red","green","yellow"]\nfor c in data:\n    if c=="W": state=(state+1)%3\n    elif state==0: state=1\n    out.append(names[state])\nreturn out',['','W','B','WWW','BBB','WBW','WWBWW','BWWBWB'],'loops')
    add('turtle_robot','Черепаха с командами','data — строка F,L,R. Робот в (0,0), смотрит на север. F делает шаг, L/R поворачивают на 90°. Верни [x,y,направление], направления N,E,S,W.','x=y=d=0; steps=[(0,1),(1,0),(0,-1),(-1,0)]\nfor c in data:\n    if c=="F": dx,dy=steps[d]; x+=dx; y+=dy\n    else: d=(d+(1 if c=="R" else -1))%4\nreturn [x,y,"NESW"[d]]',['','F','RFF','LFLF','FFFF','FRFRFRFR','RRRF','FLFRFF'],'loops')
    add('drawer_protocol','Ящики по командам','data — строка из цифр и <. Цифра кладётся поверх стопки; < снимает верхнюю, пустую не меняет. Верни сумму цифр в конечной стопке.','stack=[]\nfor c in data:\n    if c=="<":\n        if stack: stack.pop()\n    else: stack.append(int(c))\nreturn sum(stack)',['','<','12<3','000','99<<1','123<<<','5<7','<2<4<6'],'loops')
    add('cumulative_rounding','Округление каждого шага','data — целые добавки к накопителю. Старт 0. После каждой добавки округли значение вниз до ближайшего чётного. Верни конечное значение.','value=0\nfor x in data: value=(value+x)//2*2\nreturn value',A,'math_ops')
    add('increasing_pick','Осторожный собиратель','data — список чисел. Возьми первый элемент, затем каждый элемент, который не меньше суммы уже взятых. Верни взятые в исходном порядке; пустой вход [].','out=[]; total=0\nfor x in data:\n    if not out or x>=total: out.append(x); total+=x\nreturn out',A,'loops')
    add('two_bucket_fill','Два чередующихся ведра','data — неотрицательные порции воды. Разливай порции попеременно в левое и правое ведро (первая в левое), но нулевая порция не меняет очередь. Верни [объём левого,объём правого].','b=[0,0]; turn=0\nfor x in data:\n    if x: b[turn]+=x; turn^=1\nreturn b',[[],[0],[1,2,3],[0,4,0,5],[2,2,2],[7,0,1,0,9],[1],[3,4,5,6]],'loops')
    add('prefix_first_duplicate','Первое повторное имя','data — список строк. Верни первое значение, которое встретилось повторно при просмотре слева направо; если повторов нет, верни None.','seen=set()\nfor x in data:\n    if x in seen: return x\n    seen.add(x)\nreturn None',[[],['a'],['a','b','a'],['a','b','b','a'],['',''],['x','y'],['a','A','a'],['кот','дом','кот']],'dicts')
    add('basket_shelf','Полка с запретом соседства','data — список строк-названий. Удали элемент, если он равен предыдущему принятому; пропущенные не меняют предыдущее. Верни число удалений.','last=None; removed=0\nfor x in data:\n    if x==last: removed+=1\n    else: last=x\nreturn removed',[[],['a'],['a','a'],['a','b','a'],['','',''],['x','x','y','y'],['A','a'],['кот','кот','дом']],'lists')
    add('casefold_inventory','Товары без регистра','data — список строк. Считай товары одинаковыми по casefold(). Верни словарь нормализованное имя→количество, в порядке первого появления ключей.','out={}\nfor s in data:\n    k=s.casefold(); out[k]=out.get(k,0)+1\nreturn out',[[],['a'],['A','a'],['кот','КОТ','дом'],['Straße','STRASSE'],['',''],['x','y','x'],['Hi','HI','hi','Bye']],'dicts')
    add('stable_unique_length','По одному слову каждой длины','data — список строк. Сохрани первое слово каждой длины, остальные слова той же длины убери. Верни список.','seen=set(); out=[]\nfor s in data:\n    if len(s) not in seen: seen.add(len(s)); out.append(s)\nreturn out',[[],['a'],['a','b','cc'],['','x',''],['кот','дом','окно'],['ab','x','yy','zzz'],['aa','bb'],['a','aa','aaa','b']],'lists')
    add('bookend_counts','Буквы с двумя ролями','data — список непустых строк. Для каждого слова возьми первую и последнюю букву; если совпадают, считай её один раз для этого слова. Верни словарь буква→число слов, в которых она была краем.','out={}\nfor s in data:\n    for c in dict.fromkeys([s[0],s[-1]]): out[c]=out.get(c,0)+1\nreturn out',[[],['a'],['aba'],['ab','ba'],['кот','ток'],['moon','noon'],['x','xx','xy'],['red','dog','gate']],'dicts')
    add('meeting_signups','Повторная регистрация','data — список имён. Первое имя получает метку name, каждое повторное — name#2, name#3 и так далее. Исходные имена не содержат #. Верни метки.','counts={}; out=[]\nfor name in data:\n    counts[name]=counts.get(name,0)+1\n    out.append(name if counts[name]==1 else name+"#"+str(counts[name]))\nreturn out',[[],['a'],['a','a'],['x','y','x'],['',''],['A','a','A'],['кот','кот','кот'],['a','b','b','a','a']],'dicts')
    add('missing_inventory_keys','Невидимые ключи','data=[требуемые,имеющиеся] — два списка строк. Верни уникальные отсутствующие требуемые имена в порядке первого требования. Регистр важен.','wanted,available=data; have=set(available); seen=set(); out=[]\nfor x in wanted:\n    if x not in have and x not in seen: out.append(x); seen.add(x)\nreturn out',[[[],[]],[['a'],[]],[['a'],['a']],[['a','b','a'],['b']],[['x','y'],['z']],[[''],[]],[['A','a'],['a']],[['p','q','r'],['r','p']]],'dicts')
    add('first_gap_after_sort','Первая дырка между метками','data — список целых. Среди уникальных значений по возрастанию найди первую пару соседей с разницей >1 и верни меньшее+1. Если такой пары нет, None.','a=sorted(set(data))\nreturn next((x+1 for x,y in zip(a,a[1:]) if y-x>1),None)',A+[[-4,-1],[1,2,3]],'lists')
    add('nearest_occurrence_gap','Самое тесное повторение','data — список целых. Верни минимальную разницу индексов двух одинаковых значений; если повторов нет, -1.','last={}; best=None\nfor i,x in enumerate(data):\n    if x in last: best=i-last[x] if best is None else min(best,i-last[x])\n    last[x]=i\nreturn -1 if best is None else best',A,'dicts')
    add('daily_sign_balance','Баланс знаков за день','data — список чисел. За положительное получай +1, за отрицательное -1, за ноль 0. Верни первый индекс, после которого баланс стал отрицательным, либо -1.','balance=0\nfor i,x in enumerate(data):\n    balance+=(x>0)-(x<0)\n    if balance<0: return i\nreturn -1',A,'loops')
    add('crates_three_types','Коробки на троих','data — список строк типов. Слева направо укладывай коробку до появления четвёртого различного типа: тогда закрой коробку и начни новую с этого типа. Верни размеры коробок; пустой вход [].','seen=set(); sizes=[]; size=0\nfor x in data:\n    if x not in seen and len(seen)==3: sizes.append(size); seen=set(); size=0\n    seen.add(x); size+=1\nif size: sizes.append(size)\nreturn sizes',[[],['a'],['a','b','c'],['a','b','c','d'],['a']*5,['x','y','z','x','q','r'],['a','b','c','d','e','f','g'],['','x','','y','z']],'loops')
    add('growing_blocks','Блоки растущей длины','data — список. Разбей его на куски длины 1,2,3,…; последний может быть короче. Верни список кусков.','out=[]; i=0; width=1\nwhile i<len(data): out.append(data[i:i+width]); i+=width; width+=1\nreturn out',A,'lists')
    add('turning_points','Повороты без плато','data — список чисел. Сначала сожми равных соседей, затем посчитай внутренние локальные максимумы и минимумы вместе. Верни количество.','a=[x for i,x in enumerate(data) if not i or x!=data[i-1]]\nreturn sum((a[i]-a[i-1])*(a[i+1]-a[i])<0 for i in range(1,len(a)-1))',A,'lists')
    add('inventory_round_robin','Сбор из нескольких корзин','data — список списков целых. Выписывай по одному элементу из каждой корзины слева направо, пропуская исчерпанные, пока всё не закончится. Верни плоский список.','return [row[i] for i in range(max(map(len,data),default=0)) for row in data if i<len(row)]',[[],[[]],[[1,2],[3]],[[1],[2],[3]],[[1,2,3],[],[4,5]],[[0]],[[1],[],[],[2,3]],[[9,8],[7,6],[5,4]]],'lists')
    add('rain_starts','Начало дождевых эпизодов','data — список неотрицательных осадков. Верни индексы первых положительных значений каждого эпизода дождя; один сухой день внутри эпизод не разделяет, два подряд разделяют.','dry=2; out=[]\nfor i,x in enumerate(data):\n    if x>0:\n        if dry>=2: out.append(i)\n        dry=0\n    else: dry+=1\nreturn out',[[],[0],[1],[1,0,2],[1,0,0,2],[0,0,3,4,0,5],[1,0,0,0,1],[0,4,0,0,2,0,3]],'loops')
    add('reverse_inside_brackets','Текст в одной скобке','data — строка. В ней не более одной пары [ и ] в правильном порядке. Переверни текст внутри пары, сохрани скобки и внешнюю часть; без пары ничего не меняй.','l=data.find("["); r=data.find("]")\nreturn data[:l+1]+data[l+1:r][::-1]+data[r:] if 0<=l<r else data',['','abc','[abc]','x[ab]y','[]','a[b]','[кот]дом','pre[1234]post'],'strings')
    add('prefix_with_two_copies','Достаточно двух копий','data=[список,цель]. Верни минимальную длину префикса списка, содержащего цель хотя бы два раза. Если невозможно, -1.','a,target=data; count=0\nfor i,x in enumerate(a):\n    count+=x==target\n    if count==2: return i+1\nreturn -1',[[[],0],[[1],1],[[1,1],1],[[2,1,2],2],[[0,0,0],0],[[1,2,3],4],[[7,1,7,7],7],[[3,3,1],1]],'loops')
    add('gap_parking','Парковка без тесноты','data — список bool: True — место занято. Крайние свободные места разрешены. Посчитай свободные места, у которых нет занятых соседей слева и справа. Исходные места не занимай.','return sum(not used and (i==0 or not data[i-1]) and (i==len(data)-1 or not data[i+1]) for i,used in enumerate(data))',[[],[False],[True],[False,False],[True,False,False],[False,True,False],[False]*5,[True,False,False,False,True]],'lists')
    add('unary_balance','Лента плюсов и минусов','data — строка из +,-,0. Ноль сбрасывает текущий заряд в 0, плюс увеличивает, минус уменьшает. Верни максимальный модуль заряда за всё время.','charge=peak=0\nfor c in data:\n    charge=0 if c=="0" else charge+(1 if c=="+" else -1)\n    peak=max(peak,abs(charge))\nreturn peak',['','+','---','++0---','+-','000','++++-','-0--0+++'],'loops')
    add('binary_packet_edges','Пакеты с правильными краями','data — список строк из 0 и 1. Верни количество непустых строк, у которых первый и последний бит различаются, а число единиц чётное.','return sum(bool(s) and s[0]!=s[-1] and s.count("1")%2==0 for s in data)',[[],[''],['01'],['011'],['110','1010'],['0','1'],['011','110','1001'],['00110','1110','10']],'strings')
    return out
